// ⚙️ CONFIG – ustawienia bota przychodzą z panelu (http://NAS:7080) razem ze zleceniem:
//   kind = "generate" (harmonogram / „Uruchom teraz”), "publish" (kliknięcie ✅ w Telegramie)
//   albo "compose" (własny post z panelu – ✍️ Nowy post: teksty na platformy są już gotowe).
// Sekrety (klucze API, tokeny kont platform) zostają w panelu – wszystkie zapytania do API
// idą przez bramkę panelu (config.gateway), która dokleja klucze właściwe dla danego bota.
// --- język (wstawia build.py): tr('tekst po polsku', ...args) zwraca tekst w języku panelu ---
const TR_LANG = (() => {
  try {
    return $('Start: zlecenie z panelu').first().json.body.config.lang === 'en' ? 'en' : 'pl';
  } catch (e) {
    return 'pl';
  }
})();
const TR_EN = {
  "Zlecenie z panelu nie zawiera konfiguracji bota": "The request from the panel has no bot configuration",
  "Niepoprawne ID draftu: {0}": "Invalid draft ID: {0}",
  "Własny post bez platform – wybierz je w panelu": "Own post without platforms – choose them in the panel",
  "Własny post": "Own post",
  "Brak ID czatu Telegram – uzupełnij w panelu (Ustawienia → Telegram)": "No Telegram chat ID – fill it in in the panel (Settings → Telegram)",
  "Bot nie ma źródeł newsów – dodaj kanały RSS lub profile X w panelu": "The bot has no news sources – add RSS feeds or X profiles in the panel"
};
const tr = (text, ...args) => {
  const s = (TR_LANG === 'en' && TR_EN[text]) || text;
  return args.length ? s.replace(/\{(\d+)\}/g, (m, i) => (args[i] === undefined ? m : String(args[i]))) : s;
};

const body = $('Start: zlecenie z panelu').first().json.body || {};
const c = body.config || {};
const str = (v, def = '') => (v === undefined || v === null ? '' : String(v)).trim() || def;
const int = (v, def) => {
  const n = parseInt(v, 10);
  return Number.isFinite(n) && n > 0 ? n : def;
};
const bool = (v) => v === true || v === 'true';

if (!/^[a-z0-9]{3,20}$/.test(str(c.botId))) throw new Error(tr('Zlecenie z panelu nie zawiera konfiguracji bota'));
const mode = ['publish', 'compose'].includes(body.kind) ? body.kind : 'generate';
const panelUrl = str($env.POSTER_PANEL_URL, str(c.panelUrl, 'http://panel:7081')).replace(/\/+$/, '');

const feeds = (Array.isArray(c.feeds) ? c.feeds : [])
  .filter((f) => f && /^https?:\/\//i.test(String(f.url || '')))
  .map((f) => ({ url: String(f.url), label: str(f.label, String(f.url)), kind: f.kind === 'x' ? 'x' : 'rss' }));
const xSource = ['rsshub', 'apify', 'none'].includes(c.xSource) ? c.xSource : 'rsshub';
const g = c.gemini || {};
const meta = c.meta || {};

let publish = null;
if (mode === 'publish') {
  const draftId = str(body.draftId);
  // ID trafia do ścieżki pliku – tylko bezpieczne znaki
  if (!/^[A-Za-z0-9_-]{1,40}$/.test(draftId)) throw new Error(tr('Niepoprawne ID draftu: {0}', draftId.slice(0, 50)));
  publish = { draftId, chatId: body.chatId, messageId: body.messageId || null, approvedBy: str(body.approvedBy, 'Telegram') };
}
// Własny post: teksty na wybrane platformy (AI dopasowało je w panelu albo to tekst autora) i grafika z panelu
let compose = null;
if (mode === 'compose') {
  const cc = body.compose || {};
  const im = cc.image || {};
  const all = ['x', 'facebook'];
  const platforms = all.filter((k) => Array.isArray(cc.platforms) && cc.platforms.includes(k));
  if (!platforms.length) throw new Error(tr('Własny post bez platform – wybierz je w panelu'));
  compose = {
    text: str(cc.text).slice(0, 5000),
    title: str(cc.title, tr('Własny post')).slice(0, 200),
    link: /^https?:\/\/\S+$/i.test(str(cc.link)) ? str(cc.link).slice(0, 1000) : '',
    platforms,
    posts: Object.fromEntries(platforms.map((k) => [k, str((cc.posts || {})[k])])),
    // upload = zdjęcie wgrane w panelu (panel odda je węzłowi „Grafika: panel”), none = bez grafiki
    image: {
      source: ['upload', 'none'].includes(im.source) ? im.source : 'none',
      upload: /^[a-z0-9]{6,40}$/.test(str(im.upload)) ? str(im.upload) : '',
    },
    publishNow: cc.publishNow === true,
    ai: str(cc.ai).slice(0, 120),
  };
}
if (!str((c.telegram || {}).chatId)) throw new Error(tr('Brak ID czatu Telegram – uzupełnij w panelu (Ustawienia → Telegram)'));
const needFeeds = mode === 'generate';
if (needFeeds && !feeds.length && !(xSource === 'apify' && (c.xHandles || []).length)) {
  throw new Error(tr('Bot nie ma źródeł newsów – dodaj kanały RSS lub profile X w panelu'));
}

return [
  {
    json: {
      mode,
      runId: str(body.runId),
      trigger: str(body.trigger, 'manual'),
      botId: c.botId,
      botName: str(c.botName, 'Poster'),
      // język wiadomości w Telegramie i raportów (tr() w węzłach Code; prompty AI zostają po polsku)
      lang: c.lang === 'en' ? 'en' : 'pl',
      topic: str(c.topic, str(c.botName, 'newsy')),
      brandName: str(c.brandName, str(c.botName, 'Poster')),
      language: str(c.language, 'polski'),
      instructions: str(c.instructions),
      maxAgeHours: int(c.maxAgeHours, 12),
      maxCandidates: int(c.maxCandidates, 25),
      feeds,
      xSource,
      xHandles: (Array.isArray(c.xHandles) ? c.xHandles : []).map((h) => String(h).replace(/^@/, '')).filter(Boolean),
      apify: { actorId: str((c.apify || {}).actorId, 'apidojo~tweet-scraper'), maxItems: int((c.apify || {}).maxItems, 40) },
      gemini: { textModel: str(g.textModel, 'gemini-3.8-flash') },
      // publikacja od razu po zapisaniu draftu: własny post z „Publikuj teraz” w panelu
      autoPublish: !!compose && compose.publishNow,
      compose,
      enableX: bool(c.enableX),
      enableFacebook: bool(c.enableFacebook),
      meta: { graphVersion: str(meta.graphVersion, 'v24.0'), pageId: str(meta.pageId) },
      telegram: { chatId: str(c.telegram.chatId) },
      // grafika: source (zdjęcie ze źródła) | link (post z linkiem) | none
      image: { mode: ['source', 'link', 'none'].includes((c.image || {}).mode) ? c.image.mode : 'source' },
      publish,
      panelUrl,
      gateway: `${panelUrl}/gw/${c.botId}`,
      storageDir: str($env.POSTER_STORAGE_DIR, '/home/node/.n8n-files').replace(/\/+$/, ''),
    },
  },
];

// Jeden element = jeden kanał RSS (portale newsowe + profile X zamienione na RSS przez RSSHub).
const feeds = $('Config').first().json.feeds || [];
// Bez kanałów (np. tylko Apify) przepuszczamy pusty element – RSS Read zwróci błąd, który pomijamy.
if (!feeds.length) return [{ json: { url: '', label: '', kind: 'none' } }];
return feeds.map((feed) => ({ json: feed }));

// Ujednolica wpisy z RSS/RSSHub do wspólnego formatu + wylicza stabilny klucz deduplikacji (id).
// --- język (wstawia build.py): tr('tekst po polsku', ...args) zwraca tekst w języku panelu ---
const TR_LANG = (() => {
  try {
    return $('Config').first().json.lang === 'en' ? 'en' : 'pl';
  } catch (e) {
    return 'pl';
  }
})();
const TR_EN = {
  "błąd": "error"
};
const tr = (text, ...args) => {
  const s = (TR_LANG === 'en' && TR_EN[text]) || text;
  return args.length ? s.replace(/\{(\d+)\}/g, (m, i) => (args[i] === undefined ? m : String(args[i]))) : s;
};

const feedItems = $('Lista źródeł').all();
// tryb „własna strona”: AI dostaje dłuższy fragment treści artykułu (pole body)
const site = !!$('Config').first().json.site;
const articles = [];
const feedErrors = [];

// Encje HTML w jednym przejściu (bez podwójnego dekodowania), w tym liczbowe z WordPressa (&#8217; → ’)
const ENTITIES = {
  nbsp: ' ',
  quot: '"',
  apos: "'",
  lt: '<',
  gt: '>',
  amp: '&',
  hellip: '…',
  ndash: '–',
  mdash: '—',
  lsquo: '‘',
  rsquo: '’',
  ldquo: '“',
  rdquo: '”',
  bdquo: '„',
  laquo: '«',
  raquo: '»',
};
const entity = (m, e) => {
  if (e[0] !== '#') return ENTITIES[e.toLowerCase()] ?? m;
  const n = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
  return n > 0 && n < 0x110000 ? String.fromCodePoint(n) : m;
};
const decode = (s) =>
  String(s || '')
    .replace(/<(script|style)\b[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&(#\d{1,7}|#x[0-9a-f]{1,6}|[a-z]{2,8});/gi, entity)
    .replace(/\s+/g, ' ')
    .trim();

// Kanoniczny klucz: tweety → "x:<status_id>" (niezależnie od domeny x.com/twitter.com/nitter),
// artykuły → host + ścieżka bez parametrów śledzących (utm_*, fbclid...), bez "www." i końcowego "/".
// Uwaga: w sandboksie Code node nie ma klas URL/URLSearchParams – parsujemy wyrażeniami regularnymi.
const TRACKING = /^(utm_\w*|fbclid|gclid|mc_\w*|ref|ref_src|oc|cmpid|ncid|guccounter)(=|$)/i;
function parseUrl(link) {
  const m = String(link).match(/^https?:\/\/([^/?#:]+)(?::\d+)?([^?#]*)(?:\?([^#]*))?/i);
  return m ? { host: m[1].toLowerCase().replace(/^www\./, ''), path: m[2] || '', query: m[3] || '' } : null;
}
function canonical(link) {
  const tw = String(link).match(/^https?:\/\/(?:www\.|mobile\.)?(?:twitter\.com|x\.com|[^/]*nitter[^/]*)\/([^/]+)\/status(?:es)?\/(\d+)/i);
  if (tw) return { id: `x:${tw[2]}`, url: `https://x.com/${tw[1]}/status/${tw[2]}` };
  const u = parseUrl(link);
  if (!u) return null;
  const query = u.query.split('&').filter((kv) => kv && !TRACKING.test(kv));
  const q = query.length ? '?' + query.join('&') : '';
  // w postach link bez parametrów śledzących (np. utm_source=rss z kanału) – ruch z sociali nie udaje RSS-a
  return { id: `${u.host}${u.path.replace(/\/+$/, '')}${q}`, url: String(link).replace(/[?#].*$/, '') + q };
}

// Obrazki z wpisu: <enclosure>, media:content / media:thumbnail / media:group, pierwsze <img> w treści
// (RSSHub wstawia zdjęcia tweetów jako <img>). Panel wybierze z nich pierwsze pasujące.
function imagesOf(j) {
  const out = [];
  const push = (u) => {
    const url = String(u || '')
      .replace(/&amp;/g, '&')
      .trim();
    if (/^https?:\/\//i.test(url) && !out.includes(url)) out.push(url);
  };
  const enc = j.enclosure;
  if (enc && enc.url && (!enc.type || /^image\//i.test(enc.type))) push(enc.url);
  const media = (v, depth = 0) => {
    if (!v || depth > 4) return;
    if (Array.isArray(v)) return v.forEach((x) => media(x, depth + 1));
    if (typeof v !== 'object') return;
    const a = v.$ || {};
    if (a.url && (!a.medium || a.medium === 'image') && (!a.type || /^image\//i.test(a.type))) push(a.url);
    for (const k of Object.keys(v)) if (k.startsWith('media:')) media(v[k], depth + 1);
  };
  media(j['media:content']);
  media(j['media:group']);
  media(j['media:thumbnail']);
  const html = String(j['content:encoded'] || j.content || '');
  for (const m of html.matchAll(/<img\b[^>]*\bsrc=["']([^"']+)["']/gi)) push(m[1]);
  return out.slice(0, 5);
}

// Błąd węzła RSS bywa obiektem ({ message, description }) – do raportu wystarczy krótki tekst.
const errText = (e) =>
  String((e && typeof e === 'object' ? [e.message, e.description].filter(Boolean).join(' – ') || JSON.stringify(e) : e) || tr('błąd'))
    .replace(/\s+/g, ' ')
    .slice(0, 300);

// Kanał, z którego pochodzi wpis (lub błąd). W węźle Code `item.pairedItem` to tylko numer pozycji na
// wejściu, więc źródło ustalamy przez itemMatching (śledzi pochodzenie elementu przez węzeł RSS).
const feedOf = (i) => {
  try {
    return $('Lista źródeł').itemMatching(i).json || {};
  } catch (e) {
    return feedItems.length === 1 ? feedItems[0].json || {} : {};
  }
};

const input = $input.all();
for (let i = 0; i < input.length; i++) {
  const item = input[i];
  const feed = feedOf(i);
  const j = item.json || {};

  if (j.error) {
    if (feed.kind !== 'none') feedErrors.push({ feed: feed.label || feed.url, kind: feed.kind, error: errText(j.error) });
    continue;
  }
  const link = j.link || (typeof j.guid === 'string' ? j.guid : '');
  if (!link || !/^https?:\/\//i.test(link)) continue;
  const c = canonical(link);
  if (!c) continue;

  const isX = c.id.startsWith('x:') || feed.kind === 'x';
  const summary = decode(j.contentSnippet || j.content || j.summary || j.description).slice(0, 600);
  const title = decode(j.title).slice(0, 300) || summary.slice(0, 160);
  const date = new Date(j.isoDate || j.pubDate || Date.now());
  const source = feed.label || (parseUrl(link) || {}).host || 'RSS';

  articles.push({
    id: c.id,
    url: c.url,
    title,
    summary,
    // pełniejsza treść artykułu (content:encoded) – tylko dla bota „własna strona”
    ...(site ? { body: decode(j['content:encoded'] || j.content || j.summary || j.description).slice(0, 2500) } : {}),
    source,
    sourceType: isX ? 'x' : 'rss',
    author: decode(j.creator || j.author || ''),
    images: imagesOf(j),
    publishedAt: Number.isNaN(date.getTime()) ? new Date().toISOString() : date.toISOString(),
  });
}

return [{ json: { articles, feedErrors } }];

// Dokleja tweety z Apify (opcjonalne źródło X) do listy artykułów z RSS.
const base = $('Normalizuj RSS').first().json;
const articles = [...(base.articles || [])];
const feedErrors = [...(base.feedErrors || [])];

for (const item of $input.all()) {
  const t = item.json || {};
  if (t.error) {
    feedErrors.push({ feed: 'Apify', error: (t.error.message || JSON.stringify(t.error)).slice(0, 300) });
    continue;
  }
  const text = String(t.fullText || t.full_text || t.text || '')
    .replace(/\s+/g, ' ')
    .trim();
  if (t.noResults || !text) continue;

  const user = t.author?.userName || t.author?.screen_name || t.user?.screen_name || 'i';
  const rawUrl = String(t.url || t.twitterUrl || '');
  const fromUrl = rawUrl.match(/status(?:es)?\/(\d+)/);
  const statusId = String(t.id || t.id_str || (fromUrl && fromUrl[1]) || '').trim();
  if (!/^\d+$/.test(statusId)) continue;

  const date = new Date(t.createdAt || t.created_at || Date.now());
  const images = [];
  for (const m of [].concat((t.extendedEntities || t.extended_entities || {}).media || [], (t.entities || {}).media || [], t.media || [])) {
    const u = m && (m.media_url_https || m.media_url || (m.type === 'photo' && m.url));
    if (typeof u === 'string' && /^https?:\/\//.test(u) && !images.includes(u)) images.push(u);
  }
  articles.push({
    id: `x:${statusId}`,
    url: `https://x.com/${user}/status/${statusId}`,
    title: text.slice(0, 280),
    summary: text.slice(0, 600),
    source: `X @${user}`,
    sourceType: 'x',
    author: t.author?.name || user,
    images: images.slice(0, 4),
    publishedAt: Number.isNaN(date.getTime()) ? new Date().toISOString() : date.toISOString(),
  });
}

return [{ json: { articles, feedErrors } }];

// Zostawia tylko świeże wpisy (maks. wiek z panelu) i usuwa duplikaty w obrębie tego przebiegu
// (ten sam link lub ten sam tytuł z kilku źródeł). Następny węzeł pyta panel, które z nich bot
// już widział w poprzednich uruchomieniach (pamięć duplikatów – osobna dla każdego bota).
const cfg = $('Config').first().json;
const { articles = [], feedErrors = [] } = $input.first().json;

if (feedErrors.length) console.log('⚠️ Błędy źródeł:', JSON.stringify(feedErrors));

const cutoff = Date.now() - cfg.maxAgeHours * 3600 * 1000;
const normTitle = (s) =>
  String(s)
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim()
    .slice(0, 120);
const seenIds = new Set();
const seenTitles = new Set();

const fresh = articles
  .filter((a) => new Date(a.publishedAt).getTime() >= cutoff)
  .sort((a, b) => new Date(b.publishedAt) - new Date(a.publishedAt))
  .filter((a) => {
    const t = normTitle(a.title);
    if (seenIds.has(a.id) || (t && seenTitles.has(t))) return false;
    seenIds.add(a.id);
    if (t) seenTitles.add(t);
    return true;
  })
  .slice(0, 200);

// data najnowszego wpisu w kanałach (także starszego niż limit) – do komunikatu „brak nowego artykułu”
const newestAt = articles.reduce((m, a) => (a.publishedAt > m ? a.publishedAt : m), '') || null;

console.log(`Źródła: ${articles.length} wpisów, świeżych i unikalnych: ${fresh.length}`);
return [{ json: { runId: cfg.runId, total: articles.length, articles: fresh, feedErrors, newestAt } }];

// Buduje zapytanie do AI z wymuszonym schematem JSON. Panel wysyła je do dostawcy wybranego w bocie
// (Gemini albo API zgodne z OpenAI, np. Ollama). Tu edytujesz ton i zasady postów.
const cfg = $('Config').first().json;

// Wejście: odpowiedź panelu – tylko newsy, których ten bot jeszcze nie widział + jego ostatnie tematy
const res = $input.first().json || {};
const candidates = (res.articles || [])
  .slice()
  .sort((a, b) => new Date(b.publishedAt) - new Date(a.publishedAt))
  .slice(0, cfg.maxCandidates);
const nothing = 'Brak nowych newsów';
if (!candidates.length) {
  console.log(`${nothing} – kończę bez draftu.`);
  return [];
}

const fmt = (iso) => DateTime.fromISO(iso).setZone($now.zoneName).toFormat('dd.LL HH:mm');

const SCRIPT_FORMAT = `
  🎣 HOOK (0–3 s): ...
  📰 NEWS (3–10 s): ...
  🔎 ROZWINIĘCIE (10–45 s): ...
  📣 CTA (45–60 s): ...
  🎥 B-ROLL: 3–5 punktów z sugestiami ujęć/materiałów
  💬 NAPISY NA EKRANIE: 3–5 krótkich haseł`;

const instructionsBlock = cfg.instructions
  ? `\nDODATKOWE WYTYCZNE WŁAŚCICIELA PROFILU (stosuj je, o ile nie łamią zasad powyżej):\n${cfg.instructions}\n`
  : '';

// ================================================================================ newsy
// Tematy ostatnich draftów – żeby nie powtarzać tej samej historii z innego źródła.
const recentTopics = (res.recentTopics || []).slice(-15);

const newsList = candidates
  .map(
    (a, i) =>
      `[${i}] ${fmt(a.publishedAt)} | ${a.sourceType === 'x' ? 'X/Twitter' : 'RSS'} | ${a.source}\n` +
      `Tytuł: ${a.title}\n` +
      (a.summary && a.summary !== a.title ? `Treść: ${String(a.summary).slice(0, 350)}\n` : ''),
  )
  .join('\n');

const newsFields = [
  ['selected_index', 'numer wybranego newsa z listy [n].'],
  ['news_title', `krótki, rzeczowy tytuł wybranego newsa (po ${cfg.language}).`],
  ['why_selected', '1 zdanie – dlaczego ten news.'],
  [
    'post_x',
    'dynamiczny wpis na X, MAKSYMALNIE 260 znaków łącznie ze spacjami, emoji i hashtagami; mocne pierwsze słowa; 2–3 trafne hashtagi na końcu.',
  ],
  [
    'post_fb_insta',
    'angażujący post na Facebook/Instagram, 600–1500 znaków: hook w pierwszej linii, krótkie akapity, emoji jako punktory, pytanie lub CTA do komentowania, na końcu linia ze źródłem i 5–10 hashtagów (maks. 15).',
  ],
  ['script_tiktok', `skrypt wideo 30–60 s w formacie:${SCRIPT_FORMAT}`],
];
const fields = newsFields;

const system = `Jesteś doświadczonym redaktorem newsowym i social media managerem profilu "${cfg.brandName}" o tematyce: ${cfg.topic}.
Piszesz w języku: ${cfg.language}. Znasz specyfikę X (Twitter), Facebooka, Instagrama i TikToka.

ZASADY:
- Wybierz DOKŁADNIE JEDEN news: najważniejszy i najbardziej angażujący dla odbiorców tematu "${cfg.topic}" (świeżość, waga, wiarygodność, potencjał dyskusji).
- Odrzucaj reklamy, spam, clickbait, wpisy niezwiązane z tematem i tematy z listy "już opublikowane".
- Nie wymyślaj faktów, liczb, cytatów ani dat. Opieraj się wyłącznie na treści newsa. Plotkę/nieoficjalną informację oznacz jako nieoficjalną.
- Nie wstawiaj linków URL do postów. W poście FB/IG podaj nazwę źródła (np. "Źródło: CoinDesk").
- Jeśli żaden news nie nadaje się do publikacji, ustaw skip=true i podaj skip_reason (pozostałe pola mogą być puste).
${instructionsBlock}
POLA ODPOWIEDZI (czysty JSON zgodny ze schematem):
${fields.map(([k, d]) => `- ${k}: ${d}`).join('\n')}`;

const user = `TEMAT PROFILU: ${cfg.topic}

JUŻ OPUBLIKOWANE (nie powtarzaj):
${recentTopics.length ? recentTopics.map((t) => `- ${t}`).join('\n') : '- (brak)'}

NAJŚWIEŻSZE WIADOMOŚCI:
${newsList}`;

const names = ['skip', 'skip_reason', ...fields.map(([k]) => k)];
const schema = {
  type: 'OBJECT',
  properties: Object.fromEntries(
    names.map((k) => [
      k,
      k === 'skip'
        ? { type: 'BOOLEAN', description: 'true, gdy żaden news nie nadaje się do publikacji' }
